def gen(n):
    total = 0
    for i in range(n):
        got = yield total
        total += i if got is None else got

g = gen(14)
out = [next(g)]
for i in range(14 - 1):
    out.append(g.send(i * 4) if i % 2 else next(g))
print(out[-1], sum(out))

